function texte(cle) {
  return TEXTES[LANGUE][cle] !== undefined ? TEXTES[LANGUE][cle] : TEXTES.en[cle];
}

// (tour 52d) le texte écrit pour le doigt quand l'écran est tactile (TACTILE.estPresent(), tactile.js, s'il existe), sinon celui du clavier :
// texteDoigt('aideGaz') → « Tiens GAZ » (clé tac_aideGaz) ; la direction a une variante pour le mode boutons (TACTILE.etat.mode)
function texteDoigt(cle) {
  const doigt = typeof TACTILE !== 'undefined' && TACTILE && typeof TACTILE.estPresent === 'function' && TACTILE.estPresent();
  if (!doigt) return texte(cle);
  if (cle === 'aideDirection' && TACTILE.etat && TACTILE.etat.mode === 'boutons') return texte('tac_aideDirectionBoutons');
  const t = TEXTES[LANGUE]['tac_' + cle] !== undefined ? TEXTES[LANGUE]['tac_' + cle] : TEXTES.en['tac_' + cle];
  if (t !== undefined && t.includes('{d}')) return t.replace('{d}', texte(TACTILE.etat && TACTILE.etat.mode === 'boutons' ? 'tac_tourneBoutons' : 'tac_tourne'));   // (tour 53d : la bulle du premier départ dit aussi comment tourner)
  return t !== undefined ? t : texte(cle);
}

// un nombre devant un mot, accordé : nombre(1, 'saison') → « 1 saison », nombre(3, 'saison') → « 3 saisons » (texte('nb_<cle>') =
// [singulier, pluriel] ; le singulier : 0 et 1 en français, 1 seulement en anglais)
function nombre(n, cle) {
  const formes = texte('nb_' + cle), un = LANGUE === 'fr' ? Math.abs(n) < 2 : n === 1;
  return formes[un ? 0 : 1].replace('{n}', String(n).replace('.', texte('virgule')));
}

// l'élision du français (Codeur 3) : « de Alex » → « d’Alex », « que Alex » → « qu’Alex », devant un mot qui commence par une voyelle
// (pas devant un h : « de Hugo » reste, le h aspiré est fréquent dans les noms) ; appliquée aux phrases où l'on met un nom
// (interface.js : avec, journal.js : remplir, interview.js : phrase) ; en anglais, rien ne change
// l'accord d'un nombre écrit devant un mot (tour 31) : en français, le singulier à 0 et 1 (« 0 victoire », « 1 podium ») ; en
// anglais, le singulier à 1 seulement (« 1 win », « 0 wins ») ; appliqué avec elider() à toutes les phrases où l'on met des valeurs
const ACCORDS = {
  fr: [['victoires', 'victoire'], ['podiums', 'podium'], ['points', 'point'], ['titres', 'titre'], ['saisons', 'saison'], ['courses', 'course'], ['poles', 'pole'],
    ['générations', 'génération'], ['secondes', 'seconde'], ['tours', 'tour'], ['Grands Prix', 'Grand Prix'], ['places gagnées', 'place gagnée'], ['places', 'place'], ['ans', 'an'], ['pts', 'pt']],
  en: [['wins', 'win'], ['podiums', 'podium'], ['points', 'point'], ['titles', 'title'], ['seasons', 'season'], ['races', 'race'], ['poles', 'pole'],
    ['generations', 'generation'], ['seconds', 'second'], ['laps', 'lap'], ['Grands Prix', 'Grand Prix'], ['places gained', 'place gained'], ['places', 'place'], ['years', 'year'], ['pts', 'pt']],
};
function accorder(t, langue) {
  langue = langue || LANGUE;
  if (typeof t !== 'string') return t;
  const un = langue === 'fr' ? '[01]' : '1';
  for (const [pluriel, singulier] of ACCORDS[langue] || []) t = t.replace(new RegExp('(^|[^\\d,.\\u00a0])(' + un + ')([ \\u00a0])' + pluriel + '(?![\\wàâçéèêëîïôûù])', 'g'), (m, a, n, e) => a + n + e + singulier);
  return t;
}

function elider(t) {
  if (typeof t !== 'string') return t;
  t = accorder(t);
  if (LANGUE !== 'fr') return t;
  return t.replace(/(^|[\s(«“'’])([Dd]e|[Qq]ue) (?=[AEIOUYÀÂÄÆÉÈÊËÎÏÔÖŒÙÛÜaeiouyàâäæéèêëîïôöœùûü])/g, (m, avant, mot) => avant + mot.slice(0, -1) + '’');
}

